/// High-level lifecycle stage for a feature.

#\[derive(Debug,Clone,Copy,PartialEq,Eq)\]

pubenumStage{

/// Features that are still under development, not ready for external use

UnderDevelopment,

/// Experimental features made available to users through the \`/experimental\` menu

Experimental{

name:&'staticstr,

menu\_description:&'staticstr,

announcement:&'staticstr,

},

/// Stable features. The feature flag is kept for ad-hoc enabling/disabling

Stable,

/// Deprecated feature that should not be used anymore.

Deprecated,

/// The feature flag is useless but kept for backward compatibility reason.

Removed,

}

implStage{

pubfnexperimental\_menu\_name(self) -\> Option<&'staticstr>{

matchself{

Stage::Experimental{ name, .. } =\> Some(name),

Stage::UnderDevelopment \| Stage::Stable \| Stage::Deprecated \| Stage::Removed =\> None,

}

}

pubfnexperimental\_menu\_description(self) -\> Option<&'staticstr>{

matchself{

Stage::Experimental{

menu\_description, ..

} =\> Some(menu\_description),

Stage::UnderDevelopment \| Stage::Stable \| Stage::Deprecated \| Stage::Removed =\> None,

}

}

pubfnexperimental\_announcement(self) -\> Option<&'staticstr>{

matchself{

Stage::Experimental{

announcement:"", ..

} =\> None,

Stage::Experimental{ announcement, .. } =\> Some(announcement),

Stage::UnderDevelopment \| Stage::Stable \| Stage::Deprecated \| Stage::Removed =\> None,

}

}

}

/// Unique features toggled via configuration.

#\[derive(Debug,Clone,Copy,PartialEq,Eq,PartialOrd,Ord,Hash)\]

pubenumFeature{

/// Preview consumer five-hour and weekly allowance history.

AnalyticsPlanHistory,

/// Discover model catalogs for OpenAI API-key authentication.

ApiKeyModelDiscovery,

/// Forward explicit programs with builtin OpenAI API keys.

ApiKeyCyberAccessPrograms,

/// Deprecated no-op; use \`tui.fullscreen\_transcript\` instead.

TranscriptV2,

// Stable.

/// Enable the default shell tool.

ShellTool,

/// Enable the built-in local image viewer.

ViewImage,

/// Allow registration of the built-in sleep tool.

SleepTool,

/// Enable Claude-style lifecycle hooks loaded from hooks.json files.

CodexHooks,

/// Store CLI auth in the encrypted local secrets backend when keyring storage is selected.

SecretAuthStorage,

/// Automatically start the shared local daemon for eligible interactive launches.

DaemonAutoStart,

// Experimental

/// Send per-content-entry classifications in internal Responses metadata.

ContentItemKinds,

/// Record model-attempted tool calls in internal Responses metadata.

ExecutedToolCallMetadata,

/// Enable JavaScript code mode backed by the standalone host process.

CodeMode,

/// Removed compatibility flag for the configurable code-mode exec yield timeout.

CodeModeBufferedExec,

/// Run JavaScript code mode in the standalone host process.

CodeModeHost,

/// Establish the code-mode host connection during session startup.

CodeModePrewarm,

/// Terminate active code mode cells when their turn is interrupted.

CodeModeInterrupt,

/// Restrict model-visible tools to code mode entrypoints (\`exec\`, \`wait\`).

CodeModeOnly,

/// Keep eligible MCP/app and dynamic tools deferred in exec, only in Code Mode Only.

/// Ignores deferLoading, omit\_tools\_from, and namespace skip settings.

CodeModeOnlyStrictThirdPartyTools,

/// Use the single unified PTY-backed exec tool.

UnifiedExec,

/// Allow unified exec commands to allocate an interactive terminal.

UnifiedExecTty,

/// Route shell tool execution through the zsh exec bridge.

ShellZshFork,

/// Allow unified exec to compose with the zsh exec bridge.

///

/// This flag is only a composition gate. Enabling it by itself must not turn

/// on either \`unified\_exec\` or \`shell\_zsh\_fork\` because those features have

/// separate rollout and enterprise controls.

UnifiedExecZshFork,

/// Removed compatibility flag. Transcript scrollback reflow on terminal resize is always on.

stage:Stage::Stable,

default\_enabled:true,

},

