pubfnunstable\_features\_warning\_event(

effective\_features:Option<&Table>,

suppress\_unstable\_features\_warning:bool,

features:&Features,

config\_path:&str,

) -\> Option<Event>{

if suppress\_unstable\_features\_warning {

returnNone;

}

letmut under\_development\_feature\_keys = Vec::new();

ifletSome(table) = effective\_features {

for(key, value)in table {

let is\_enabled = value.as\_bool() == Some(true)

\|\| value

.as\_table()

.and\_then(\|table\| table.get("enabled"))

.and\_then(toml::Value::as\_bool)

== Some(true);

if !is\_enabled {

continue;

}

letSome(spec) = FEATURES.iter().find(\|spec\| spec.key == key.as\_str())else{

continue;

};

if !features.enabled(spec.id){

continue;

}

ifmatches!(spec.stage,Stage::UnderDevelopment){

under\_development\_feature\_keys.push(spec.key.to\_string());

}

}

}

if under\_development\_feature\_keys.is\_empty(){

returnNone;

}

under\_development\_feature\_keys.sort();

let under\_development\_feature\_keys = under\_development\_feature\_keys.join(", ");

let message = format!(

"Under-development features enabled: {under\_development\_feature\_keys}. Under-development features are incomplete and may behave unpredictably. To suppress this warning, set \`suppress\_unstable\_features\_warning = true\` in {config\_path}."

);

Some(Event{

id:String::new(),

msg:EventMsg::Warning(WarningEvent{ message }),

})

}

